export default function P2({students, hideAge=true}: {students: Student[], hideAge: boolean}) {
    const jsx = students.map((student) => (
        <div key={student.id}>
            {student.name}
            {/* 条件判断: 当 hideAge 为 false 时，显示年龄 */}
            {!hideAge && <div>{student.age}</div>}
        </div>
    ))
    return (
        <React.Fragment>
            {jsx}
        </React.Fragment>
    )
}
